import {evaluate,summarize,names,VERSION,nextDraw,choose,top} from './engine.js';
export function recompute(history,previous,now=new Date().toISOString()){
 const run=evaluate(history.draws),current=run.records.filter(r=>r.pool===52),summary=summarize(current),best=summary.filter(s=>s.model!=='Uniform').sort((a,b)=>b.lower-a.lower)[0];
 const winner=current.length>=100&&best.lower>0?best.model:'Uniform',index=names.indexOf(winner),target=nextDraw(run.trainingThrough);
 const parts=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'America/Toronto',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(now)).map(p=>[p.type,p.value]));
 if(`${parts.year}-${parts.month}-${parts.day}T${parts.hour}:${parts.minute}`>=target+'T22:30')throw Error('Official results are not current enough to create the next forecast. Try again later.');
 const ledger=structuredClone(previous),seed=Number(target.replaceAll('-',''));
 if(!ledger.some(p=>p.target===target&&p.engineVersion===VERSION))ledger.push({game:'lotto-max',target,generatedAt:now,trainingThrough:run.trainingThrough,engineVersion:VERSION,storage:'this browser',model:winner,numbers:index===0?choose(run.probabilities[index],seed):top(run.probabilities[index],seed),probabilities:run.probabilities[index],candidates:names.map((model,j)=>({model,probabilities:run.probabilities[j],numbers:j===0?choose(run.probabilities[j],seed):top(run.probabilities[j],seed)})),status:'experimental',reason:winner==='Uniform'?'No candidate cleared the promotion threshold on current-era chronological tests.':'Candidate cleared exploratory promotion gate; live confirmation still required.'});
 for(const p of ledger){const actual=history.draws.find(r=>r.date===p.target);if(actual&&!p.result&&p.trainingThrough<p.target)p.result={actual:actual.numbers,hits:p.numbers.filter(x=>actual.numbers.includes(x)).length,scoredAt:now,candidates:(p.candidates||[]).map(c=>({model:c.model,hits:c.numbers.filter(x=>actual.numbers.includes(x)).length,actualNumberProbabilities:actual.numbers.map(n=>({number:n,probability:c.probabilities[n-1]}))}))}}
 return {history,ledger,analysis:{generatedAt:now,version:VERSION,summary,allEras:summarize(run.records),byEra:run.byEra,records:run.records.slice(-104),forecast:ledger.find(p=>p.target===target&&p.engineVersion===VERSION)}};
}
export function mergeLedger(published,local){const rows=new Map(published.map(p=>[p.target+'|'+p.engineVersion,p]));for(const p of local){const key=p.target+'|'+p.engineVersion;if(!rows.has(key))rows.set(key,p)}return [...rows.values()].sort((a,b)=>a.target.localeCompare(b.target))}
